probes.setup:
globalThis.ARC = { state: { data: { workbooks: [] } } };
globalThis.SHEET = {
  id: 'q3-s1', name: 'Sheet1', rowCount: 20, colCount: 12,
  seedRange: { r1: 0, c1: 0, r2: 5, c2: 2 },
  cells: {
    A1: 'Region', B1: 'Sales', C1: 'Status',
    A2: 'East', B2: '1200', C2: 'Open',
    A3: 'North', B3: '800', C3: 'Closed',
    A4: 'South', B4: '700', C4: 'Open'
  },
  sel: { r1: 0, c1: 0, r2: 0, c2: 0 },
  rules: [],
  filter: { r1: 0, c1: 0, r2: 5, c2: 2, conds: { '2': { type: 'condition', op: 'contains', value: 'Open' } } },
  pivot: null
};
globalThis.WB = { id: 'wb-q3sales', name: 'Q3 Sales', updatedAt: '2024-09-30 09:15', activeSheet: 'q3-s1', sheets: [SHEET] };
ARC.state.data.workbooks = [WB];

probes.precondition:
assert.strictEqual(rowHidden(SHEET, 1), false);
assert.strictEqual(rowHidden(SHEET, 2), true);
assert.strictEqual(rowHidden(SHEET, 3), false);

probes.check:
shiftCells(SHEET, 'row', 1, 1, false);
assert.strictEqual(SHEET.cells.A3, 'East');
assert.strictEqual(SHEET.cells.C3, 'Open');
assert.strictEqual(SHEET.cells.A5, 'South');
assert.strictEqual(rowHidden(SHEET, 2), false);
assert.strictEqual(rowHidden(SHEET, 3), true);
assert.strictEqual(rowHidden(SHEET, 4), false);

probes.setup:
globalThis.SHEET = {
  id: 'blank-1', name: 'Sheet1', rowCount: 20, colCount: 6,
  cells: {}, sel: { r1: 0, c1: 0, r2: 0, c2: 0 }, rules: [], filter: null, pivot: null
};

probes.precondition:
assert.strictEqual(SHEET.colCount, 6);
assert.strictEqual(SHEET.rowCount, 20);
assert.strictEqual(offsetFormula('=C1', 0, 1), '=D1');
assert.strictEqual(offsetFormula('=C1', 0, -1), '=B1');
assert.strictEqual(offsetFormula('=A20', -1, 0), '=A19');
assert.strictEqual(offsetFormula('=$F$1', 0, 1), '=$F$1');

probes.check:
const right = offsetFormula('=F1', 0, 1);
const down = offsetFormula('=A20', 1, 0);
assert.strictEqual(right, '=#REF!');
assert.strictEqual(down, '=#REF!');
